import app from "@/store/app";
import ajax from "@/utils/ajax";
import { action, computed, observable, makeObservable } from "mobx";

class Store {
    @observable key = '';
    @action
    setKey = () => {
        this.key = Math.random().toString(32);
    }

    // 路由type分类
    @observable type = 'system';
    @action
    setType = (type) => {
        this.type = type;
    }

    constructor() {
        makeObservable(this);
    }

    @computed get classId(){
        if(app.appId){
            // 如果存在应用id，则说明是非基础管理系统
            return app.appId;
        }
        return this.type;
    }

    /**
     * 获取沟通列表
     */
    getTableData = (params) => {
        return ajax.post('/apijson/get', {
            "Menu[]": {
                "query": 2,
                "count": 0,
                "Menu": {
                    ...params,
                    "classId": this.classId,
                    '@order': 'sort+',
                    "@column": ['id', 'name', 'icon', 'sort', 'parentId', 'mode', 'isShow', 'isActive', 'path', 'componentPath', 'updatedAt'].join(',')
                },
            },
            "info@":"/Menu[]/info"
        }).then((res) => {
            return {
                list: res.Menu,
                total: res.info.total
            }
        })
    }


    /**
     * 获取沟通详情
     */
    getDetail = (item) => {
        return ajax.post('/apijson/get', {
            Menu: {
                id: item.id
            }
        }).then((res) => {
            return {
                ...res.Menu,
            };
        })
    }
}

export default new Store();