export default () => {

	return useObserver(() => {

		const  pageRef = useRef<any>();

		const tableHeaderTitle = useMemo(() => {
			return [];
		},[store.type])

		const schema = useMemo(() => getSchema(), [])


		return (
			<SchemaPage
				ref={pageRef}
				schema={schema}
				rowSelection
				treeBool
				className="page-container"
				api={{
					find: ({ pageSize, current, ...params}) => {
						return store.getTableData(params)
					},
					get: (item) => {
						return store.getDetail(item);
					},
					post: (form) => {
						return ajax.post('/apijson/post', {
							"Menu": {
								...form,
								"classId": store.classId,
							},
						}).then(() => {
							Message.success({
								content: '新增成功',
							});
							store.setKey();
						})
					},
					put: (form, data) => {
						if(form.parentId === data.id){
							Message.error(`上级菜单不能选择自己`)
							return Promise.reject();
						}
						// console.log('/apijson/put', form, data)
						return ajax.post('/apijson/put', {
							"Menu": {
								id: data.id,
								...form,
							}
						}).then(() => {
							Message.success({
								content: '更新成功'
							})
							store.setKey();
						})
					},
					del: (item) => {
						return new Promise((resolve, reject) => {
							Modal.confirm({
								title: `请确认是否要删除当前数据`,
								onOk: () => {
									return ajax.post('/apijson/delete', {
										"Menu": {
											id: item.id
										}
									}).then((res) => {
										Message.success({
											content: '删除成功',
										})
										store.setKey();
										resolve(res)
									}).catch(reject);
								},
								onCancel: reject,
							})
						})
					}
				}}
				schemForm={{
					filterKeys: ['parentId', 'type', 'icon', 'name', 'sort', 'isLink', 'path', 'mode', 'pageId', 'componentPath', 'isShow', 'isActive'],
					generagteProps: {
						cols: 12,
						widgets: {
							ParentIdField
						}
					}
				}}
				schemaTable={{
					pagination: false,
					filterKeys: ['name', 'icon', 'mode', 'sort', 'path', 'isShow',  'isActive', 'updatedAt'],
					headerTitle: tableHeaderTitle
				}}
				queryForm={{
					filterKeys: ['name', 'isActive'],
				}}
			/>
		)
	})
}